// AuthoringServiceHandler is an implementation of the
// vrooli.plan_manager.v1.authoring.AuthoringService service.
type AuthoringServiceHandler interface {
	// StartSession begins a new authoring session for a plan title/slug
	// (PM-AUTHOR-001).
	StartSession(context.Context, *connect.Request[authoring.StartSessionRequest]) (*connect.Response[authoring.StartSessionResponse], error)
	// GetSession returns the full authoring session state. This is the explicit
	// full-state read endpoint: normal mutations return only focused progress and
	// a mutation summary, so a UI/operator that needs the whole session graph must
	// ask for it deliberately (read-after-write) rather than relying on a session
	// echo from every mutation.
	GetSession(context.Context, *connect.Request[authoring.GetSessionRequest]) (*connect.Response[authoring.GetSessionResponse], error)
	// GetSection returns one section's current state.
	GetSection(context.Context, *connect.Request[authoring.GetSectionRequest]) (*connect.Response[authoring.GetSectionResponse], error)
	// SubmitSection records authored content for a section and re-validates it.
	SubmitSection(context.Context, *connect.Request[authoring.SubmitSectionRequest]) (*connect.Response[authoring.SubmitSectionResponse], error)
	// SubmitFields applies a BATCH of section/phase-field writes under one
	// session lock with one save — one call can carry a single field, a whole
	// phase, or the whole plan. Items apply independently (never
	// all-or-nothing): each returns accepted/rejected + violations + a one-line
	// parse summary. The single-field RPCs (SubmitSection/SubmitPhaseField)
	// remain as wrappers over the same apply path.
	SubmitFields(context.Context, *connect.Request[authoring.SubmitFieldsRequest]) (*connect.Response[authoring.SubmitFieldsResponse], error)
	// Next returns the next section that still needs author input (or signals the
	// session is structurally complete).
	Next(context.Context, *connect.Request[authoring.NextRequest]) (*connect.Response[authoring.NextResponse], error)
	// ContinueAuthoring returns the single recommended next wizard action across
	// section, context, phase, validation-review, and finalize states.
	ContinueAuthoring(context.Context, *connect.Request[authoring.ContinueAuthoringRequest]) (*connect.Response[authoring.ContinueAuthoringResponse], error)
	// ValidateStructure runs the structure-validation gate over the whole session
	// (PM-AUTHOR-002).
	ValidateStructure(context.Context, *connect.Request[authoring.ValidateStructureRequest]) (*connect.Response[authoring.ValidateStructureResponse], error)
	// Autofill orchestrates the mechanical-section autofill behind seams.
	Autofill(context.Context, *connect.Request[authoring.AutofillRequest]) (*connect.Response[authoring.AutofillResponse], error)
	// SubmitRelevantContextItem records one global or phase-scoped setup item in
	// the authoring session. Accepted items finalize into the plans domain's
	// shared RelevantContextItem contract.
	SubmitRelevantContextItem(context.Context, *connect.Request[authoring.SubmitRelevantContextItemRequest]) (*connect.Response[authoring.SubmitRelevantContextItemResponse], error)
	// ListRelevantContext returns accepted context items from the session without
	// changing wizard position.
	ListRelevantContext(context.Context, *connect.Request[authoring.ListRelevantContextRequest]) (*connect.Response[authoring.ListRelevantContextResponse], error)
	// UpdateRelevantContextItem replaces one accepted global or phase-scoped
	// context item in place (by item id) so a bad accepted item discovered in
	// preview is corrected without deleting the whole phase/session. Legal only
	// before finalize.
	UpdateRelevantContextItem(context.Context, *connect.Request[authoring.UpdateRelevantContextItemRequest]) (*connect.Response[authoring.UpdateRelevantContextItemResponse], error)
	// RemoveRelevantContextItem deletes one accepted global or phase-scoped context
	// item (by item id) before finalize, recomputing structure violations so a
	// resulting gate (e.g. removing the only phase context) is reported with its
	// recovery action.
	RemoveRelevantContextItem(context.Context, *connect.Request[authoring.RemoveRelevantContextItemRequest]) (*connect.Response[authoring.RemoveRelevantContextItemResponse], error)
	// DiscoverContextCandidates runs the guided context-discovery seams for one
	// or more concepts and stores pending candidates on the authoring session.
	DiscoverContextCandidates(context.Context, *connect.Request[authoring.DiscoverContextCandidatesRequest]) (*connect.Response[authoring.DiscoverContextCandidatesResponse], error)
	// AcceptContextCandidate promotes one pending discovery candidate into the
	// session's global or phase-scoped relevant-context list.
	AcceptContextCandidate(context.Context, *connect.Request[authoring.AcceptContextCandidateRequest]) (*connect.Response[authoring.AcceptContextCandidateResponse], error)
	// RejectContextCandidate records why a discovered candidate is not relevant.
	RejectContextCandidate(context.Context, *connect.Request[authoring.RejectContextCandidateRequest]) (*connect.Response[authoring.RejectContextCandidateResponse], error)
	// ApplyContextDisposition closes a pending discovery batch in one call:
	// named takes are accepted, named drops are rejected, and remaining shortlist
	// items are swept unless they require a high-confidence drop reason.
	ApplyContextDisposition(context.Context, *connect.Request[authoring.ApplyContextDispositionRequest]) (*connect.Response[authoring.ApplyContextDispositionResponse], error)
	// SuggestReferences queries search-hub's Answer projection from the session's
	// title + scope + technical approach and stores reviewable reference candidates
	// (routed by locator shape — only hits resolving to a [CODE:]/[DOC:]/[REQ:]
	// locator are kept) on the session. Degrades honestly to no candidates when
	// search-hub is down/empty; suggestions never auto-fill the references section.
	SuggestReferences(context.Context, *connect.Request[authoring.SuggestReferencesRequest]) (*connect.Response[authoring.SuggestReferencesResponse], error)
	// ListReferenceCandidates returns the session's reference candidates without
	// changing wizard position.
	ListReferenceCandidates(context.Context, *connect.Request[authoring.ListReferenceCandidatesRequest]) (*connect.Response[authoring.ListReferenceCandidatesResponse], error)
	// AcceptReferenceCandidate promotes one pending reference candidate into the
	// references section (with an optional inline edit of the locator). Only
	// accepted candidates satisfy the references gate.
	AcceptReferenceCandidate(context.Context, *connect.Request[authoring.AcceptReferenceCandidateRequest]) (*connect.Response[authoring.AcceptReferenceCandidateResponse], error)
	// RejectReferenceCandidate records why a suggested reference is not relevant.
	RejectReferenceCandidate(context.Context, *connect.Request[authoring.RejectReferenceCandidateRequest]) (*connect.Response[authoring.RejectReferenceCandidateResponse], error)
	// ApplyReferenceDisposition closes a pending reference discovery batch in one
	// call: named takes are accepted, named drops are rejected, and remaining
	// shortlist items are swept unless they require a high-confidence drop reason.
	ApplyReferenceDisposition(context.Context, *connect.Request[authoring.ApplyReferenceDispositionRequest]) (*connect.Response[authoring.ApplyReferenceDispositionResponse], error)
	// AddPhase appends one structured phase draft to the session.
	AddPhase(context.Context, *connect.Request[authoring.AddPhaseRequest]) (*connect.Response[authoring.AddPhaseResponse], error)
	// MovePhase reorders a structured phase draft before or after another draft
	// without rewriting the phase's authored content.
	MovePhase(context.Context, *connect.Request[authoring.MovePhaseRequest]) (*connect.Response[authoring.MovePhaseResponse], error)
	// GetPhase returns one structured phase draft plus the API-owned guided step
	// for its next missing field.
	GetPhase(context.Context, *connect.Request[authoring.GetPhaseRequest]) (*connect.Response[authoring.GetPhaseResponse], error)
	// SubmitPhaseField records one structured phase field and validates that
	// phase immediately.
	SubmitPhaseField(context.Context, *connect.Request[authoring.SubmitPhaseFieldRequest]) (*connect.Response[authoring.SubmitPhaseFieldResponse], error)
	// NextPhase returns the first structured phase that still needs input.
	NextPhase(context.Context, *connect.Request[authoring.NextPhaseRequest]) (*connect.Response[authoring.NextPhaseResponse], error)
	// PreviewPlan renders the in-progress session to its markdown review artifact
	// WITHOUT persisting, so a human/agent can review the plan before finalize.
	PreviewPlan(context.Context, *connect.Request[authoring.PreviewPlanRequest]) (*connect.Response[authoring.PreviewPlanResponse], error)
	// Finalize validates structure then writes the produced plan through the plans
	// domain, returning the persisted plan.
	Finalize(context.Context, *connect.Request[authoring.FinalizeRequest]) (*connect.Response[authoring.FinalizeResponse], error)
}

